    swap_introspect!();
    # [doc = " Swaps the values at two mutable locations of the same type, without"] # [doc = " deinitializing either."] # [doc = ""] # [doc = " But for the following exceptions, this function is semantically"] # [doc = " equivalent to [`mem::swap`]:"] # [doc = ""] # [doc = " * It operates on raw pointers instead of references. When references are"] # [doc = "   available, [`mem::swap`] should be preferred."] # [doc = ""] # [doc = " * The two pointed-to values may overlap. If the values do overlap, then the"] # [doc = "   overlapping region of memory from `x` will be used. This is demonstrated"] # [doc = "   in the second example below."] # [doc = ""] # [doc = " * The operation is \"untyped\" in the sense that data may be uninitialized or otherwise violate"] # [doc = "   the requirements of `T`. The initialization state is preserved exactly."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Behavior is undefined if any of the following conditions are violated:"] # [doc = ""] # [doc = " * Both `x` and `y` must be [valid] for both reads and writes. They must remain valid even when the"] # [doc = "   other pointer is written. (This means if the memory ranges overlap, the two pointers must not"] # [doc = "   be subject to aliasing restrictions relative to each other.)"] # [doc = ""] # [doc = " * Both `x` and `y` must be properly aligned."] # [doc = ""] # [doc = " Note that even if `T` has size `0`, the pointers must be properly aligned."] # [doc = ""] # [doc = " [valid]: self#safety"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Swapping two non-overlapping regions:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ptr;"] # [doc = ""] # [doc = " let mut array = [0, 1, 2, 3];"] # [doc = ""] # [doc = " let (x, y) = array.split_at_mut(2);"] # [doc = " let x = x.as_mut_ptr().cast::<[u32; 2]>(); // this is `array[0..2]`"] # [doc = " let y = y.as_mut_ptr().cast::<[u32; 2]>(); // this is `array[2..4]`"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     ptr::swap(x, y);"] # [doc = "     assert_eq!([2, 3, 0, 1], array);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Swapping two overlapping regions:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ptr;"] # [doc = ""] # [doc = " let mut array: [i32; 4] = [0, 1, 2, 3];"] # [doc = ""] # [doc = " let array_ptr: *mut i32 = array.as_mut_ptr();"] # [doc = ""] # [doc = " let x = array_ptr as *mut [i32; 3]; // this is `array[0..3]`"] # [doc = " let y = unsafe { array_ptr.add(1) } as *mut [i32; 3]; // this is `array[1..4]`"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     ptr::swap(x, y);"] # [doc = "     // The indices `1..3` of the slice overlap between `x` and `y`."] # [doc = "     // Reasonable results would be for to them be `[2, 3]`, so that indices `0..3` are"] # [doc = "     // `[1, 2, 3]` (matching `y` before the `swap`); or for them to be `[0, 1]`"] # [doc = "     // so that indices `1..4` are `[0, 1, 2]` (matching `x` before the `swap`)."] # [doc = "     // This implementation is defined to make the latter choice."] # [doc = "     assert_eq!([1, 0, 1, 2], array);"] # [doc = " }"] # [doc = " ```"] # [inline] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_const_stable (feature = "const_swap" , since = "1.85.0")] # [rustc_diagnostic_item = "ptr_swap"] pub const unsafe fn swap < T > (x : * mut T , y : * mut T) { let mut tmp = MaybeUninit :: < T > :: uninit () ; unsafe { copy_nonoverlapping (x , tmp . as_mut_ptr () , 1) ; copy (y , x , 1) ; copy_nonoverlapping (tmp . as_ptr () , y , 1) ; } }
