mkfn!{
    read_volatile_introspect!();
    # [doc = " Performs a volatile read of the value from `src` without moving it."] # [doc = ""] # [doc = " Volatile operations are intended to act on I/O memory. As such, they are considered externally"] # [doc = " observable events (just like syscalls, but less opaque), and are guaranteed to not be elided or"] # [doc = " reordered by the compiler across other externally observable events. With this in mind, there"] # [doc = " are two cases of usage that need to be distinguished:"] # [doc = ""] # [doc = " - When a volatile operation is used for memory inside an [allocation], it behaves exactly like"] # [doc = "   [`read`], except for the additional guarantee that it won't be elided or reordered (see"] # [doc = "   above). This implies that the operation will actually access memory and not e.g. be lowered to"] # [doc = "   reusing data from a previous read. Other than that, all the usual rules for memory accesses"] # [doc = "   apply (including provenance).  In particular, just like in C, whether an operation is volatile"] # [doc = "   has no bearing whatsoever on questions involving concurrent accesses from multiple threads."] # [doc = "   Volatile accesses behave exactly like non-atomic accesses in that regard."] # [doc = ""] # [doc = " - Volatile operations, however, may also be used to access memory that is _outside_ of any Rust"] # [doc = "   allocation. In this use-case, the pointer does *not* have to be [valid] for reads. This is"] # [doc = "   typically used for CPU and peripheral registers that must be accessed via an I/O memory"] # [doc = "   mapping, most commonly at fixed addresses reserved by the hardware. These often have special"] # [doc = "   semantics associated to their manipulation, and cannot be used as general purpose memory."] # [doc = "   Here, any address value is possible, including 0 and [`usize::MAX`], so long as the semantics"] # [doc = "   of such a read are well-defined by the target hardware. The provenance of the pointer is"] # [doc = "   irrelevant, and it can be created with [`without_provenance`]. The access must not trap. It"] # [doc = "   can cause side-effects, but those must not affect Rust-allocated memory in any way. This"] # [doc = "   access is still not considered [atomic], and as such it cannot be used for inter-thread"] # [doc = "   synchronization."] # [doc = ""] # [doc = " Note that volatile memory operations where T is a zero-sized type are noops and may be ignored."] # [doc = ""] # [doc = " [allocation]: crate::ptr#allocated-object"] # [doc = " [atomic]: crate::sync::atomic#memory-model-for-atomic-accesses"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Like [`read`], `read_volatile` creates a bitwise copy of `T`, regardless of whether `T` is"] # [doc = " [`Copy`]. If `T` is not [`Copy`], using both the returned value and the value at `*src` can"] # [doc = " [violate memory safety][read-ownership]. However, storing non-[`Copy`] types in volatile memory"] # [doc = " is almost certainly incorrect."] # [doc = ""] # [doc = " Behavior is undefined if any of the following conditions are violated:"] # [doc = ""] # [doc = " * `src` must be either [valid] for reads, or it must point to memory outside of all Rust"] # [doc = "   allocations and reading from that memory must:"] # [doc = "   - not trap, and"] # [doc = "   - not cause any memory inside a Rust allocation to be modified."] # [doc = ""] # [doc = " * `src` must be properly aligned."] # [doc = ""] # [doc = " * Reading from `src` must produce a properly initialized value of type `T`."] # [doc = ""] # [doc = " Note that even if `T` has size `0`, the pointer must be properly aligned."] # [doc = ""] # [doc = " [valid]: self#safety"] # [doc = " [read-ownership]: read#ownership-of-the-returned-value"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Basic usage:"] # [doc = ""] # [doc = " ```"] # [doc = " let x = 12;"] # [doc = " let y = &x as *const i32;"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     assert_eq!(std::ptr::read_volatile(y), 12);"] # [doc = " }"] # [doc = " ```"] # [inline] # [stable (feature = "volatile" , since = "1.9.0")] # [track_caller] # [rustc_diagnostic_item = "ptr_read_volatile"] pub unsafe fn read_volatile < T > (src : * const T) -> T { unsafe { ub_checks :: assert_unsafe_precondition ! (check_language_ub , "ptr::read_volatile requires that the pointer argument is aligned" , (addr : * const () = src as * const () , align : usize = align_of ::< T > () ,) => ub_checks :: maybe_is_aligned (addr , align)) ; intrinsics :: volatile_load (src) } }
}

