mkitem!{# [doc = " Creates a `const` raw pointer to a place, without creating an intermediate reference."] # [doc = ""] # [doc = " `addr_of!(expr)` is equivalent to `&raw const expr`. The macro is *soft-deprecated*;"] # [doc = " use `&raw const` instead."] # [doc = ""] # [doc = " It is still an open question under which conditions writing through an `addr_of!`-created"] # [doc = " pointer is permitted. If the place `expr` evaluates to is based on a raw pointer, then the"] # [doc = " result of `addr_of!` inherits all permissions from that raw pointer. However, if the place is"] # [doc = " based on a reference, local variable, or `static`, then until all details are decided, the same"] # [doc = " rules as for shared references apply: it is UB to write through a pointer created with this"] # [doc = " operation, except for bytes located inside an `UnsafeCell`. Use `&raw mut` (or [`addr_of_mut`])"] # [doc = " to create a raw pointer that definitely permits mutation."] # [doc = ""] # [doc = " Creating a reference with `&`/`&mut` is only allowed if the pointer is properly aligned"] # [doc = " and points to initialized data. For cases where those requirements do not hold,"] # [doc = " raw pointers should be used instead. However, `&expr as *const _` creates a reference"] # [doc = " before casting it to a raw pointer, and that reference is subject to the same rules"] # [doc = " as all other references. This macro can create a raw pointer *without* creating"] # [doc = " a reference first."] # [doc = ""] # [doc = " See [`addr_of_mut`] for how to create a pointer to uninitialized data."] # [doc = " Doing that with `addr_of` would not make much sense since one could only"] # [doc = " read the data, and that would be Undefined Behavior."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The `expr` in `addr_of!(expr)` is evaluated as a place expression, but never loads from the"] # [doc = " place or requires the place to be dereferenceable. This means that `addr_of!((*ptr).field)`"] # [doc = " still requires the projection to `field` to be in-bounds, using the same rules as [`offset`]."] # [doc = " However, `addr_of!(*ptr)` is defined behavior even if `ptr` is null, dangling, or misaligned."] # [doc = ""] # [doc = " Note that `Deref`/`Index` coercions (and their mutable counterparts) are applied inside"] # [doc = " `addr_of!` like everywhere else, in which case a reference is created to call `Deref::deref` or"] # [doc = " `Index::index`, respectively. The statements above only apply when no such coercions are"] # [doc = " applied."] # [doc = ""] # [doc = " [`offset`]: pointer::offset"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " **Correct usage: Creating a pointer to unaligned data**"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ptr;"] # [doc = ""] # [doc = " #[repr(packed)]"] # [doc = " struct Packed {"] # [doc = "     f1: u8,"] # [doc = "     f2: u16,"] # [doc = " }"] # [doc = ""] # [doc = " let packed = Packed { f1: 1, f2: 2 };"] # [doc = " // `&packed.f2` would create an unaligned reference, and thus be Undefined Behavior!"] # [doc = " let raw_f2 = ptr::addr_of!(packed.f2);"] # [doc = " assert_eq!(unsafe { raw_f2.read_unaligned() }, 2);"] # [doc = " ```"] # [doc = ""] # [doc = " **Incorrect usage: Out-of-bounds fields projection**"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " use std::ptr;"] # [doc = ""] # [doc = " #[repr(C)]"] # [doc = " struct MyStruct {"] # [doc = "     field1: i32,"] # [doc = "     field2: i32,"] # [doc = " }"] # [doc = ""] # [doc = " let ptr: *const MyStruct = ptr::null();"] # [doc = " let fieldptr = unsafe { ptr::addr_of!((*ptr).field2) }; // Undefined Behavior ⚠\u{fe0f}"] # [doc = " ```"] # [doc = ""] # [doc = " The field projection `.field2` would offset the pointer by 4 bytes,"] # [doc = " but the pointer is not in-bounds of an allocation for 4 bytes,"] # [doc = " so this offset is Undefined Behavior."] # [doc = " See the [`offset`] docs for a full list of requirements for inbounds pointer arithmetic; the"] # [doc = " same requirements apply to field projections, even inside `addr_of!`. (In particular, it makes"] # [doc = " no difference whether the pointer is null or dangling.)"] # [stable (feature = "raw_ref_macros" , since = "1.51.0")] # [rustc_macro_transparency = "semitransparent"] pub macro addr_of ($ place : expr) { & raw const $ place }}
mkitem!{# [doc = " Creates a `mut` raw pointer to a place, without creating an intermediate reference."] # [doc = ""] # [doc = " `addr_of_mut!(expr)` is equivalent to `&raw mut expr`. The macro is *soft-deprecated*;"] # [doc = " use `&raw mut` instead."] # [doc = ""] # [doc = " Creating a reference with `&`/`&mut` is only allowed if the pointer is properly aligned"] # [doc = " and points to initialized data. For cases where those requirements do not hold,"] # [doc = " raw pointers should be used instead. However, `&mut expr as *mut _` creates a reference"] # [doc = " before casting it to a raw pointer, and that reference is subject to the same rules"] # [doc = " as all other references. This macro can create a raw pointer *without* creating"] # [doc = " a reference first."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " The `expr` in `addr_of_mut!(expr)` is evaluated as a place expression, but never loads from the"] # [doc = " place or requires the place to be dereferenceable. This means that `addr_of_mut!((*ptr).field)`"] # [doc = " still requires the projection to `field` to be in-bounds, using the same rules as [`offset`]."] # [doc = " However, `addr_of_mut!(*ptr)` is defined behavior even if `ptr` is null, dangling, or misaligned."] # [doc = ""] # [doc = " Note that `Deref`/`Index` coercions (and their mutable counterparts) are applied inside"] # [doc = " `addr_of_mut!` like everywhere else, in which case a reference is created to call `Deref::deref`"] # [doc = " or `Index::index`, respectively. The statements above only apply when no such coercions are"] # [doc = " applied."] # [doc = ""] # [doc = " [`offset`]: pointer::offset"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " **Correct usage: Creating a pointer to unaligned data**"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ptr;"] # [doc = ""] # [doc = " #[repr(packed)]"] # [doc = " struct Packed {"] # [doc = "     f1: u8,"] # [doc = "     f2: u16,"] # [doc = " }"] # [doc = ""] # [doc = " let mut packed = Packed { f1: 1, f2: 2 };"] # [doc = " // `&mut packed.f2` would create an unaligned reference, and thus be Undefined Behavior!"] # [doc = " let raw_f2 = ptr::addr_of_mut!(packed.f2);"] # [doc = " unsafe { raw_f2.write_unaligned(42); }"] # [doc = " assert_eq!({packed.f2}, 42); // `{...}` forces copying the field instead of creating a reference."] # [doc = " ```"] # [doc = ""] # [doc = " **Correct usage: Creating a pointer to uninitialized data**"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::{ptr, mem::MaybeUninit};"] # [doc = ""] # [doc = " struct Demo {"] # [doc = "     field: bool,"] # [doc = " }"] # [doc = ""] # [doc = " let mut uninit = MaybeUninit::<Demo>::uninit();"] # [doc = " // `&uninit.as_mut().field` would create a reference to an uninitialized `bool`,"] # [doc = " // and thus be Undefined Behavior!"] # [doc = " let f1_ptr = unsafe { ptr::addr_of_mut!((*uninit.as_mut_ptr()).field) };"] # [doc = " unsafe { f1_ptr.write(true); }"] # [doc = " let init = unsafe { uninit.assume_init() };"] # [doc = " ```"] # [doc = ""] # [doc = " **Incorrect usage: Out-of-bounds fields projection**"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " use std::ptr;"] # [doc = ""] # [doc = " #[repr(C)]"] # [doc = " struct MyStruct {"] # [doc = "     field1: i32,"] # [doc = "     field2: i32,"] # [doc = " }"] # [doc = ""] # [doc = " let ptr: *mut MyStruct = ptr::null_mut();"] # [doc = " let fieldptr = unsafe { ptr::addr_of_mut!((*ptr).field2) }; // Undefined Behavior ⚠\u{fe0f}"] # [doc = " ```"] # [doc = ""] # [doc = " The field projection `.field2` would offset the pointer by 4 bytes,"] # [doc = " but the pointer is not in-bounds of an allocation for 4 bytes,"] # [doc = " so this offset is Undefined Behavior."] # [doc = " See the [`offset`] docs for a full list of requirements for inbounds pointer arithmetic; the"] # [doc = " same requirements apply to field projections, even inside `addr_of_mut!`. (In particular, it"] # [doc = " makes no difference whether the pointer is null or dangling.)"] # [stable (feature = "raw_ref_macros" , since = "1.51.0")] # [rustc_macro_transparency = "semitransparent"] pub macro addr_of_mut ($ place : expr) { & raw mut $ place }}